def calculate_shipping_cost(weight_kg, destination_zone):
    """
    Calculate shipping cost based on weight and zone.
    Zone 1: $2.00 base + $0.50/kg
    Zone 2: $3.00 base + $0.75/kg
    Zone 3: $4.00 base + $1.00/kg
    """
    rates = {
        1: (2.00, 0.50),
        2: (3.00, 0.75),
        3: (4.00, 1.00)
    }

    if destination_zone not in rates:
        raise ValueError(f"Unknown destination zone: {destination_zone}")

    base_rate, per_kg_rate = rates[destination_zone]
    cost = base_rate + (weight_kg * per_kg_rate)

    return round(cost, 2)

