import json

def calculate_total_price(items):
    """计算购物车中所有商品的总价"""
    total = 0.0
    for item in items:
        price = item.get('price', 0.0)
        quantity = item.get('quantity', 1)
        if price < 0 or quantity < 0:
            raise ValueError("价格和数量不能为负数")
        total += price * quantity
    return round(total, 2)

def apply_discount(total_price, discount_code):
    """根据折扣码应用折扣"""
    discounts = {
        'SAVE10': 0.90,
        'SAVE20': 0.80,
        'VIP': 0.75
    }
    if discount_code in discounts:
        return round(total_price * discounts[discount_code], 2)
    return total_price

def generate_invoice(customer_name, items, discount_code=None):
    """生成发票数据"""
    subtotal = calculate_total_price(items)
    final_price = apply_discount(subtotal, discount_code) if discount_code else subtotal

    invoice = {
        'customer': customer_name,
        'items': items,
        'subtotal': subtotal,
        'final_price': final_price,
        'currency': 'USD'
    }

    return json.dumps(invoice, indent=2)
