import csv
from datetime import datetime

def calculate_monthly_sales(data_file):
    """Calculate total sales for each month from CSV data."""
    monthly_sales = {}

    with open(data_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                date = datetime.strptime(row['date'], '%Y-%m-%d')
                month_key = date.strftime('%Y-%m')
                amount = float(row['amount'])
                monthly_sales[month_key] = monthly_sales.get(month_key, 0) + amount
            except (ValueError, KeyError):
                continue

    return {k: round(v, 2) for k, v in sorted(monthly_sales.items())}
