import json
from datetime import datetime

def process_order(order_data):
    """Process a standard business order and calculate total price."""
    try:
        items = order_data.get("items", [])
        if not items:
            raise ValueError("Order must contain at least one item")

        total = 0.0
        for item in items:
            quantity = int(item.get("quantity", 1))
            price = float(item.get("price", 0.0))
            if quantity < 0 or price < 0:
                raise ValueError("Quantity and price must be non-negative")
            total += quantity * price

        # Apply 10% discount for orders over $100
        if total > 100.0:
            total *= 0.9

        return {
            "order_id": order_data.get("id"),
            "total_price": round(total, 2),
            "processed_at": datetime.now().isoformat()
        }
    except (ValueError, TypeError) as e:
        return {"error": str(e), "order_id": order_data.get("id")}

if __name__ == "__main__":
    sample_order = {
        "id": "ORD-20231001-001",
        "items": [
            {"name": "Widget", "quantity": 5, "price": 19.99},
            {"name": "Gadget", "quantity": 2, "price": 49.99}
        ]
    }
    result = process_order(sample_order)
    print(json.dumps(result, indent=2))
