import csv
from datetime import datetime

def process_sales_data(filename):
    """读取CSV销售数据并计算月度总收入"""
    monthly_revenue = {}
    with open(filename, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                date_obj = datetime.strptime(row['date'], '%Y-%m-%d')
                month_key = date_obj.strftime('%Y-%m')
                amount = float(row['amount'])
                monthly_revenue[month_key] = monthly_revenue.get(month_key, 0) + amount
            except (ValueError, KeyError) as e:
                print(f"跳过无效行: {row}, 错误: {e}")
    return {k: round(v, 2) for k, v in sorted(monthly_revenue.items())}

if __name__ == '__main__':
    results = process_sales_data('sales_2023.csv')
    for month, revenue in results.items():
        print(f"{month}: ${revenue}")
