def calculate_discount(price, member_level):
    """
    Calculate final price based on member level.

    Args:
        price (float): Original price
        member_level (int): Member level (1-3)

    Returns:
        float: Final price after discount
    """
    if member_level == 1:
        discount = 0.95
    elif member_level == 2:
        discount = 0.90
    elif member_level == 3:
        discount = 0.85
    else:
        discount = 1.0

    return round(price * discount, 2)
